/* =========================================================================
 *  js/lang/index.js — the four-mode text layer
 *
 *  Modes: zh (简体中文), en (English), brl-zh (盲文·中文), brl-en (盲文·English).
 *  Every user-facing string goes through t(). The packs are complete and are
 *  generated by tools/build_lang.js from tools/texts.js; a missing key is a
 *  build error (scripts/i18n_check.js reports it).
 *
 *  Loaded from index.html BEFORE js/mod.js — mod.js and every layer file call
 *  t() at addLayer() time.
 * ========================================================================= */

/* global LANG_PACKS */
var LANG_PACKS = LANG_PACKS || {}

var LANG_MODES = [
	{ code: "zh", label: "中文" },
	{ code: "en", label: "English" },
	{ code: "brl-zh", label: "盲文 · 中文" },
	{ code: "brl-en", label: "Braille · English" },
]

// Bumped to .v2 so the new brl-en default takes effect once; afterwards the
// player's own choice is remembered under the same key.
var LANG_STORE = "the-braille-tree-v83pqm.lang.v2"
var LANG_PREF = "brl-en"

;(function initLang() {
	try {
		var saved = localStorage.getItem(LANG_STORE)
		if (saved) LANG_PREF = saved
	} catch (e) { LANG_PREF = "brl-en" }
	if (!LANG_PACKS[LANG_PREF]) LANG_PREF = "brl-en"
	// Braille cells are symbols, not letters: browsers find no soft-wrap
	// opportunities between them, so long braille text overflows sideways.
	if ((LANG_PREF === "brl-zh" || LANG_PREF === "brl-en") && typeof document !== "undefined" && document.documentElement) {
		document.documentElement.classList.add("brl-mode")
	}
})()

function isBrailleMode() {
	return LANG_PREF === "brl-zh" || LANG_PREF === "brl-en"
}

/** The one accessor. Pack -> zh pack -> literal -> key. */
function t(key, fallback) {
	var pack = LANG_PACKS[LANG_PREF]
	if (pack && typeof pack[key] === "string") return pack[key]
	if (LANG_PACKS.zh && typeof LANG_PACKS.zh[key] === "string") return LANG_PACKS.zh[key]
	return fallback !== undefined ? fallback : key
}

/** Alias used by the layer files; keeps the call sites short. */
function T(key, fallback) { return t(key, fallback) }

/** format() a value, brailleizing it in the two braille modes. */
function num(value) {
	var s = (typeof value === "string") ? value : format(value)
	if (isBrailleMode()) return brailleNumber(s, LANG_PREF)
	return s
}

/** formatWhole() a value, brailleizing it in the two braille modes. */
function numWhole(value) {
	var s = (typeof value === "string") ? value : formatWhole(value)
	if (isBrailleMode()) return brailleNumber(s, LANG_PREF)
	return s
}

/** Locked-layer tooltip. Kept as a helper so each language can order the
 *  sentence naturally instead of gluing English fragments together. */
function lockTooltipText(layer) {
	var res = tmp[layer].baseResource
	return t("ui.reach", "Reach") + " " + num(formatWhole(tmp[layer].requires)) + " " + res + " "
		+ t("ui.toUnlock", "to unlock (You have") + " " + num(formatWhole(tmp[layer].baseAmount)) + " " + res
		+ t("ui.closeParen", ")")
}

/** Name of the current milestone-display option, in the active language. */
function msDisplayName() {
	var i = MS_SETTINGS.indexOf(options.msDisplay)
	if (i === 1) return t("ui.msLastAutoIncomplete", "LAST, AUTO, INCOMPLETE")
	if (i === 2) return t("ui.msAutomationIncomplete", "AUTOMATION, INCOMPLETE")
	if (i === 3) return t("ui.msIncomplete", "INCOMPLETE")
	if (i === 4) return t("ui.msNone", "NONE")
	return t("ui.msAll", "ALL")
}

/** Tab labels. Keys stay stable English identifiers so a save made in one
 *  language still points at a real tab after switching to another. */
function tabLabel(layer, family, tab) {
	var key = "tab." + tab
	return t(key, tab)
}

function setGameLang(code) {
	if (!LANG_PACKS[code]) return
	LANG_PREF = code
	try { localStorage.setItem(LANG_STORE, code) } catch (e) { /* ignore */ }
	location.reload()
}

/* ---- settings UI (rendered through display-text, which is v-html) -------- */

function langSettingsHtml() {
	var sel = ""
	for (var i = 0; i < LANG_MODES.length; i++) {
		sel += '<option value="' + LANG_MODES[i].code + '"'
			+ (LANG_PREF === LANG_MODES[i].code ? " selected" : "") + '>'
			+ LANG_MODES[i].label + '</option>'
	}
	return ''
		+ '<div style="text-align:left;max-width:760px;margin:0 auto;">'
		+ '<h3>' + t("ui.lang") + '</h3>'
		+ '<p style="opacity:.75">' + t("ui.langBlurb") + '</p>'
		+ '<select onchange="setGameLang(this.value)" style="font-size:1.1em;padding:6px 10px;margin:6px 0;">'
		+ sel + '</select>'
		+ '<p style="opacity:.6;font-size:.9em">' + t("ui.langBrailleNote") + '</p>'
		+ '</div>'
}
